// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 depositAmount, uint8 actorSeed) public {
        vm.assume(depositAmount > 0 && depositAmount <= 1000 ether);
        address actor = address(uint160(uint256(keccak256(abi.encode(actorSeed)))));
        vm.assume(actor != address(0));
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();
        uint256 balBefore = address(c).balance;
        vm.prank(actor);
        c.withdrawAll();
        uint256 balAfter = address(c).balance;
        assertTrue(balAfter == balBefore - depositAmount);
    }
}
